"""Regenerate `tests/fixtures/sustainment/row_fraction_seal.json`.

The fixture is produced BY the converter, never hand-written: leg A (here) and
leg B (cortex's real reader) share it so the two cannot each derive their own
expectation and drift while both stay green.

2026-10-21: adds the SEVERAL-BOX row cortex asked for -- *"7f: please make one
fixture in leg B's family a several-box row, so cortex's leg covers the union
and its note."* (cortex packet of 2026-10-21, section 5.)

It lives BESIDE the fixture rather than in `scratchpad/`, which holds no
tracked files: the fixture's own `_note` names this script, and a note that
points at an untracked path is a promise of reproducibility that nobody else
can keep.

Run:  .venv\\Scripts\\python tests\\fixtures\\sustainment\\gen_row_fraction_seal.py
"""
import io
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(os.path.dirname(os.path.dirname(HERE)))
sys.path.insert(0, REPO)

from doc_tools.utils import sustainment_merge as merge  # noqa: E402

OUT = os.path.join(HERE, "row_fraction_seal.json")

PAGE = 3
DIMS = {"width": 1700.0, "height": 2200.0}

#: One parts-table cell, 200-DPI US-letter. Every edge divides INEXACTLY on
#: purpose, so the seal covers the 6-digit rounding and not just exact
#: arithmetic.
PIXEL_BBOX = [223.0, 917.0, 661.0, 953.0]

#: A two-line cell. Chosen so each edge of the union comes from a DIFFERENT
#: box -- x0 and y1 from the second, y0 and x1 from the first -- which a
#: transposed min/max would get wrong. All eight edges divide inexactly.
PIXEL_BBOXES_MULTI = [[223.0, 917.0, 661.0, 953.0],
                      [189.0, 959.0, 587.0, 995.0]]

RENDER_SIZES = [{"width": 850.0, "height": 1100.0},
                {"width": 1024.0, "height": 1325.0},
                {"width": 1700.0, "height": 2200.0}]


def prov(bboxes):
    return {"page_number": PAGE, "page_dims": dict(DIMS), "bboxes": bboxes,
            "match_method": "text_layer_cell", "match_confidence": 1.0}


def cell(pixels, rendered):
    """The reference cell: cortex's `scaleBox` on the OLD (pixel) shape. The
    conversion is correct exactly when the fraction shape lands here too.

    MIRRORS THEIR ARITHMETIC, not merely their maths. `scaleBox`
    (`cortex-ui` `src/lib/bboxScale.ts`) takes a scale factor FIRST
    (`sx = rendered.width / pageDims.width`) and then multiplies. Dividing and
    then multiplying is algebraically identical and differs in the last bits:
    `223 / 1700 * 850` is 111.49999999999999 where `223 * (850 / 1700)` is
    111.5. Far below any tolerance here -- but this file is the REFERENCE the
    other leg compares against, so it should be what their code computes, not
    something equal to it.
    """
    x0, y0, x1, y1 = pixels
    sx = rendered["width"] / DIMS["width"]
    sy = rendered["height"] / DIMS["height"]
    return {"left": x0 * sx, "top": y0 * sy,
            "width": (x1 - x0) * sx, "height": (y1 - y0) * sy}


def union_pixels(boxes):
    return [min(b[0] for b in boxes), min(b[1] for b in boxes),
            max(b[2] for b in boxes), max(b[3] for b in boxes)]


single = prov([list(PIXEL_BBOX)])
multi = prov([list(b) for b in PIXEL_BBOXES_MULTI])
u = union_pixels(PIXEL_BBOXES_MULTI)

doc = {
    "_note": (
        "The row-conversion seal fixture (architect 2026-10-21 item 3). "
        "Generated BY doc-tools' converter -- regenerate with "
        "tests/fixtures/sustainment/gen_row_fraction_seal.py, never by hand. "
        "doc-tools' leg A "
        "asserts this file is current; cortex's leg B reads the same numbers "
        "through the real reader. `multi_box` covers the union and its note "
        "(cortex's ask, 2026-10-21)."
    ),
    "page_dims": dict(DIMS),
    "pixel_bbox": list(PIXEL_BBOX),
    "old_shape": {"page": PAGE, "bbox": list(PIXEL_BBOX),
                  "page_dims": dict(DIMS), "units": "px"},
    "new_shape": merge._row_wire_evidence_ref(single, "text_layer_cell"),
    "render_sizes": [dict(r) for r in RENDER_SIZES],
    "expected_cells": [{"rendered": dict(r), "cell": cell(PIXEL_BBOX, r)}
                       for r in RENDER_SIZES],

    "multi_box": {
        "_note": (
            "A two-line cell. The row emits BOTH boxes in `bboxes`; the wire "
            "ref carries their union with note \"2 boxes\". cortex outlines "
            "the union and captions the note, and leaves a union out of crop "
            "sharing -- a union is not \"this exact cell\"."
        ),
        "pixel_bboxes": [list(b) for b in PIXEL_BBOXES_MULTI],
        "union_pixels": list(u),
        "fractions": merge._row_fractions(multi),
        "new_shape": merge._row_wire_evidence_ref(multi, "text_layer_cell"),
        "expected_union_cells": [{"rendered": dict(r), "cell": cell(u, r)}
                                 for r in RENDER_SIZES],
        "expected_box_cells": [
            {"rendered": dict(r), "cells": [cell(b, r) for b in PIXEL_BBOXES_MULTI]}
            for r in RENDER_SIZES],
    },
}

with io.open(OUT, "w", encoding="utf-8", newline="\n") as fh:
    json.dump(doc, fh, indent=2)
    fh.write("\n")

print("wrote", OUT)
print("new_shape      :", json.dumps(doc["new_shape"]))
print("multi new_shape:", json.dumps(doc["multi_box"]["new_shape"]))
print("multi fractions:", json.dumps(doc["multi_box"]["fractions"]))
